sysauto_script.script:
var reminderDays = [90, 60, 45, 30, 15, 7, 3, 1];

var gr = new GlideRecord(
    'x_1956466_vendor_0_vendor_main'
);

gr.addQuery('state', 'active');
gr.query();

while (gr.next()) {

    gs.info(
        "Processing Vendor: " +
        gr.vendor_name
    );

    // Current Date
    var today = new GlideDate();

    // Expiry Date
    var expiry = new GlideDate();
    expiry.setValue(gr.expiry_date);

    // Difference Between Dates
    var duration = GlideDate.subtract(
        today,
        expiry
    );

    // Remaining Days
    var daysLeft = Math.abs(
        duration.getDayPart()
    );

    gs.info(
        "Days Left: " + daysLeft
    );


    if (reminderDays.indexOf(daysLeft) >= 0) {

        if (gr.last_reminder_milestone != daysLeft) {
            gs.info(
                "Reminder Triggered for " +
                daysLeft +
                " days"
            );

            gs.eventQueue(
                'x_1956466_vendor_0.vendor.expiry.reminde',
                gr,
                daysLeft.toString(),
                gr.contact_email.toString()
            );


            gr.last_reminder_milestone = daysLeft;
            gr.last_reminder_date = new GlideDate();
            gr.update();

            gs.info(
                "Reminder Event Queued"
            );

        } else {
            gs.info(
                "Reminder already sent for " +
                daysLeft +
                " days"
            );
        }
    } else {
        gs.info('No reminders needed');
    }

    if (today.after(expiry)) {
        gs.info(
            "Vendor Expired"
        );

        gr.state = 'expired';
        gr.active = false;

        gr.update();
    }
}
